#include "embedded.h"

// lagsw_kmod_images.h is generated by backends/kmod/xmake.lua (kmod/modules/embed.lua) and only exists when the build embeds modules
#ifdef LAGSW_KMOD_EMBEDDED
#	include "lagsw_kmod_images.h"
#endif

namespace kmodb {

std::vector<ModuleImage> embedded_images()
{
	std::vector<ModuleImage> images;
#ifdef LAGSW_KMOD_EMBEDDED
	for (const LagswKmodImage& image : kLagswKmodImages)
		images.push_back({image.data, static_cast<size_t>(image.size)});
#endif
	return images;
}

}  // namespace kmodb
